export const getMechanism = (id: string | null) => MECHANISMS.find(m=>m.id===id) ?? MECHANISMS[0];
export function neighbors(mechanism: Mechanism, id: string): Set<string> {
  return new Set([id,...mechanism.flows.flatMap(e=>e.from===id?[e.to]:e.to===id?[e.from]:[])]);
}
